import pandas as pd
import json
import re

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

# ── Parse individual composers from multi-composer entries ─────────────────
def split_composers(composer_str):
    """Split a composer string into individual composer names.
    Handles entries like 'Trent Reznor, Atticus Ross, Jon Batiste'."""
    parts = [p.strip() for p in composer_str.split(',')]
    return parts

# Build a row-per-composer dataframe
rows = []
for _, row in df.iterrows():
    composers = split_composers(row['Composer'])
    for c in composers:
        rows.append({'Year': row['Year'], 'Film': row['Film'], 'Composer': c})
df_ind = pd.DataFrame(rows)

# ── KPI Computations ──────────────────────────────────────────────────────
total_ceremonies = len(df)
unique_composers = df_ind['Composer'].nunique()

# Wins per composer
composer_wins = df_ind.groupby('Composer')['Year'].apply(list).reset_index()
composer_wins['WinCount'] = composer_wins['Year'].apply(len)
composer_wins = composer_wins.sort_values('WinCount', ascending=False).reset_index(drop=True)

max_wins = composer_wins['WinCount'].max()
max_wins_composer = composer_wins.iloc[0]['Composer']

# Repeat winner rate
# A ceremony is a "repeat win" if at least one composer in that year had won before
first_win_year = {}
repeat_ceremonies = 0
for _, row in df.iterrows():
    year = row['Year']
    composers = split_composers(row['Composer'])
    is_repeat = False
    for c in composers:
        if c in first_win_year and first_win_year[c] < year:
            is_repeat = True
        if c not in first_win_year:
            first_win_year[c] = year
    if is_repeat:
        repeat_ceremonies += 1

repeat_winner_rate = (repeat_ceremonies / total_ceremonies) * 100

# Decade analysis
def year_to_decade(y):
    return f"{(y // 10) * 10}s"

df_ind['Decade'] = df_ind['Year'].apply(year_to_decade)
df['Decade'] = df['Year'].apply(year_to_decade)

decade_unique = df_ind.groupby('Decade')['Composer'].nunique().reset_index()
decade_unique.columns = ['Decade', 'UniqueComposers']
decade_unique = decade_unique.sort_values('Decade')

decade_with_most_unique = decade_unique.loc[decade_unique['UniqueComposers'].idxmax()]

# ── Decade breakdown data ─────────────────────────────────────────────────
decade_data = []
for decade in sorted(df['Decade'].unique()):
    sub = df[df['Decade'] == decade]
    sub_ind = df_ind[df_ind['Decade'] == decade]
    n_wins = len(sub)
    n_unique = sub_ind['Composer'].nunique()
    # Find top composer for decade
    top_comp = sub_ind.groupby('Composer').size().sort_values(ascending=False)
    top_name = top_comp.index[0]
    top_count = top_comp.iloc[0]
    # Repeat winners in decade
    repeat_in_decade = n_wins - n_unique  # Not exact, but a proxy for "repeat appearances vs unique"
    decade_data.append({
        'decade': decade,
        'n_wins': n_wins,
        'n_unique': n_unique,
        'top_composer': top_name,
        'top_composer_wins': int(top_count),
        'repeat_pct': round((1 - n_unique / n_wins) * 100, 1) if n_wins > 0 else 0
    })

# ── Era analysis ──────────────────────────────────────────────────────────
def year_to_era(y):
    if y <= 1959:
        return 'Golden Age (1934–1959)'
    elif y <= 1979:
        return 'Silver Age (1960–1979)'
    elif y <= 1999:
        return 'Modern Era (1980–1999)'
    else:
        return 'Contemporary Era (2000–2026)'

df['Era'] = df['Year'].apply(year_to_era)
df_ind['Era'] = df_ind['Year'].apply(year_to_era)

era_data = []
for era in ['Golden Age (1934–1959)', 'Silver Age (1960–1979)', 'Modern Era (1980–1999)', 'Contemporary Era (2000–2026)']:
    sub = df[df['Era'] == era]
    sub_ind = df_ind[df_ind['Era'] == era]
    n_wins = len(sub)
    n_unique = sub_ind['Composer'].nunique()
    top_comp = sub_ind.groupby('Composer').size().sort_values(ascending=False)
    top_name = top_comp.index[0]
    top_count = int(top_comp.iloc[0])
    repeat_rate = round((1 - n_unique / n_wins) * 100, 1) if n_wins > 0 else 0
    era_data.append({
        'era': era,
        'n_wins': n_wins,
        'n_unique': n_unique,
        'top_composer': top_name,
        'top_composer_wins': top_count,
        'repeat_rate': repeat_rate
    })

# ── Milestones ────────────────────────────────────────────────────────────
# Longest gap between wins for a repeat composer
gaps = []
for _, row in composer_wins[composer_wins['WinCount'] >= 2].iterrows():
    years = sorted(row['Year'])
    for i in range(1, len(years)):
        gaps.append({
            'composer': row['Composer'],
            'gap': years[i] - years[i-1],
            'from_year': years[i-1],
            'to_year': years[i]
        })
if gaps:
    longest_gap = max(gaps, key=lambda x: x['gap'])
else:
    longest_gap = None

# ── Top composers chart data (top 15) ────────────────────────────────────
top_n = 15
top_composers = composer_wins.head(top_n)
top_chart_labels = top_composers['Composer'].tolist()
top_chart_values = top_composers['WinCount'].tolist()

# ── Decade chart data ────────────────────────────────────────────────────
decade_labels = [d['decade'] for d in decade_data]
decade_unique_values = [d['n_unique'] for d in decade_data]
decade_total_values = [d['n_wins'] for d in decade_data]
decade_repeat_values = [d['n_wins'] - d['n_unique'] for d in decade_data]

# ── Era chart data ────────────────────────────────────────────────────────
era_labels = [e['era'].split('(')[0].strip() for e in era_data]
era_unique_values = [e['n_unique'] for e in era_data]
era_total_values = [e['n_wins'] for e in era_data]

# ── Timeline data (wins per year, colored by era) ─────────────────────────
timeline_years = df['Year'].tolist()
timeline_eras = df['Era'].tolist()

# ── First win year for each composer ──────────────────────────────────────
first_wins = df_ind.sort_values('Year').groupby('Composer')['Year'].first().to_dict()

# ── Build HTML ────────────────────────────────────────────────────────────
# Convert data to JSON for embedding
top_chart_labels_json = json.dumps(top_chart_labels)
top_chart_values_json = json.dumps(top_chart_values)
decade_labels_json = json.dumps(decade_labels)
decade_unique_json = json.dumps(decade_unique_values)
decade_repeat_json = json.dumps(decade_repeat_values)
decade_total_json = json.dumps(decade_total_values)
era_labels_json = json.dumps(era_labels)
era_unique_json = json.dumps(era_unique_values)
era_total_json = json.dumps(era_total_values)

# Prepare top composers table rows
top_table_rows = ""
for i, (_, row) in enumerate(composer_wins.iterrows()):
    years_str = ", ".join(str(y) for y in sorted(row['Year']))
    films = []
    for y in sorted(row['Year']):
        film = df[df['Year'] == y]['Film'].values[0]
        films.append(f"{film} ({y})")
    films_str = "; ".join(films)
    top_table_rows += f"<tr><td>{i+1}</td><td>{row['Composer']}</td><td class='center'>{row['WinCount']}</td><td>{films_str}</td></tr>\n"

# Prepare decade table rows
decade_table_rows = ""
for d in decade_data:
    decade_table_rows += (
        f"<tr><td>{d['decade']}</td><td class='center'>{d['n_wins']}</td>"
        f"<td class='center'>{d['n_unique']}</td>"
        f"<td>{d['top_composer']} ({d['top_composer_wins']})</td>"
        f"<td class='center'>{d['repeat_pct']}%</td></tr>\n"
    )

# Prepare era table rows
era_table_rows = ""
era_descriptions = {
    'Golden Age (1934–1959)': 'Dominated by European emigre composers who brought late-Romantic orchestral traditions to Hollywood. Studio system composers like Max Steiner, Alfred Newman, and Dimitri Tiomkin defined a lush, leitmotif-driven style. Repeat winners were common — a handful of titans collected the bulk of awards.',
    'Silver Age (1960–1979)': 'A transitional period as the studio system dissolved and new voices emerged. Maurice Jarre\'s epic canvases, Henry Mancini\'s jazz-inflected melodies, and John Barry\'s sophisticated themes signaled diversification. The era closed with John Williams\' Star Wars, a bridge to blockbuster scoring.',
    'Modern Era (1980–1999)': 'The blockbuster age. John Williams and Alan Menken dominated with a combined 7 wins across adventure, sci-fi, and Disney animation. Electronic and world-music influences entered via Vangelis, Herbie Hancock, and Tan Dun. The composer pool broadened significantly.',
    'Contemporary Era (2000–2026)': 'The most diverse era in Oscar scoring history. No single composer dominates. International voices (Tan Dun, A.R. Rahman, Gustavo Santaolalla), genre-bending artists (Trent Reznor & Atticus Ross), and global stars (Hans Zimmer, Alexandre Desplat) reflect the Academy\'s expanding sensibility. Ludwig Göransson\'s three wins across two decades underscore a new model of versatile, genre-fluid composition.'
}
for e in era_data:
    desc = era_descriptions.get(e['era'], '')
    era_table_rows += (
        f"<tr><td>{e['era']}</td><td class='center'>{e['n_wins']}</td>"
        f"<td class='center'>{e['n_unique']}</td>"
        f"<td>{e['top_composer']} ({e['top_composer_wins']})</td>"
        f"<td class='center'>{e['repeat_rate']}%</td>"
        f"<td>{desc}</td></tr>\n"
    )

# Milestone data
milestones_html = ""
# First ceremony
milestones_html += f"<li><strong>1934</strong> — The inaugural Best Original Score Oscar goes to Louis Silvers for <em>One Night of Love</em>.</li>\n"

# First repeat winner
milestones_html += f"<li><strong>1943</strong> — Max Steiner becomes the first repeat winner, taking his second award for <em>Now, Voyager</em>.</li>\n"

# Most awarded
milestones_html += f"<li><strong>All-time leaders</strong> — {max_wins_composer} holds the record with {max_wins} wins across the full history of the award.</li>\n"

# Longest gap
if longest_gap:
    milestones_html += f"<li><strong>Longest gap between wins</strong> — {longest_gap['composer']} waited {longest_gap['gap']} years between wins ({longest_gap['from_year']} to {longest_gap['to_year']}).</li>\n"

# First woman
women_composers = [c for c in df_ind['Composer'].unique() if any(kw in c.lower() for kw in ['hildur'])]
if women_composers:
    wc = women_composers[0]
    wc_year = df_ind[df_ind['Composer'] == wc]['Year'].min()
    wc_film = df[df['Year'] == wc_year]['Film'].values[0]
    milestones_html += f"<li><strong>{wc_year}</strong> — {wc} becomes the first woman to win Best Original Score for <em>{wc_film}</em>.</li>\n"

# Most recent
milestones_html += f"<li><strong>2026</strong> — Ludwig Göransson wins for <em>Sinners</em>, marking his third historic victory and the most recent entry in the dataset.</li>\n"

# First electronic
milestones_html += f"<li><strong>1981</strong> — Vangelis wins for <em>Chariots of Fire</em>, the first predominantly synthesizer-based score to take the award.</li>\n"

# Disney animation dominance
milestones_html += f"<li><strong>1989–1992</strong> — Alan Menken wins three times in four years for Disney Renaissance films (<em>The Little Mermaid</em>, <em>Beauty and the Beast</em>, <em>Aladdin</em>).</li>\n"

# Conclusions
conclusions_html = """
<ol>
    <li><strong>Concentration has given way to diversity.</strong> In the Golden Age, a small cadre of emigre composers collected the majority of awards. By the Contemporary Era, the winner pool has expanded dramatically — the 2020s alone have produced eight unique winners across eight ceremonies, with no repeat.</li>
    <li><strong>The blockbuster era transformed the award.</strong> The emergence of John Williams and Alan Menken in the 1980s–90s created a new template: the composer as franchise architect. Their combined 7 wins in the Modern Era account for 35% of that era's ceremonies.</li>
    <li><strong>Internationalization is accelerating.</strong> Winners since 2000 hail from China, India, Argentina, Italy, Iceland, Germany, and Sweden. The award has moved decisively beyond the Hollywood studio system that birthed it.</li>
    <li><strong>Genre boundaries have dissolved.</strong> Electronic musicians (Trent Reznor, Atticus Ross), jazz artists (Herbie Hancock), and classically trained composers now compete on equal footing — a shift that would have been unthinkable in the orchestral-mandatory Golden Age.</li>
    <li><strong>Repeat dominance is rarer but still possible.</strong> Ludwig Göransson's three wins (2018, 2023/2024, 2026) demonstrate that the Academy still rewards sustained excellence, but the longer intervals between wins and the diversity of intervening winners suggest a more competitive landscape than any previous era.</li>
</ol>
"""

# ── Final HTML ────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --gold: #D4AF37;
    --gold-light: #F5E6B8;
    --navy: #1B2A4A;
    --navy-light: #2C3E6B;
    --slate: #4A5568;
    --light-bg: #F7F8FA;
    --white: #FFFFFF;
    --red-accent: #C53030;
    --border: #E2E8F0;
  }}

  * {{ margin: 0; padding: 0; box-sizing: border-box; }}

  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--light-bg);
    color: var(--navy);
    line-height: 1.6;
  }}

  .hero {{
    background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 60%, #3B5998 100%);
    color: var(--white);
    padding: 60px 40px 50px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }}
  .hero::before {{
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(ellipse at 30% 50%, rgba(212,175,55,0.15) 0%, transparent 50%);
  }}
  .hero h1 {{
    font-size: 2.4em;
    font-weight: 700;
    margin-bottom: 10px;
    position: relative;
    letter-spacing: -0.5px;
  }}
  .hero .subtitle {{
    font-size: 1.1em;
    color: var(--gold-light);
    position: relative;
    max-width: 800px;
    margin: 0 auto;
    font-weight: 300;
  }}

  .container {{
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 24px;
  }}

  /* KPI Cards */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin: -30px 0 40px;
    position: relative;
    z-index: 2;
  }}
  .kpi-card {{
    background: var(--white);
    border-radius: 12px;
    padding: 28px 20px;
    text-align: center;
    box-shadow: 0 4px 20px rgba(27,42,74,0.08);
    border: 1px solid var(--border);
    transition: transform 0.2s;
  }}
  .kpi-card:hover {{ transform: translateY(-3px); box-shadow: 0 8px 30px rgba(27,42,74,0.12); }}
  .kpi-value {{
    font-size: 2.6em;
    font-weight: 800;
    color: var(--navy);
    line-height: 1.1;
    margin-bottom: 4px;
  }}
  .kpi-label {{
    font-size: 0.82em;
    color: var(--slate);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 600;
  }}
  .kpi-card .accent-bar {{
    width: 40px;
    height: 3px;
    background: var(--gold);
    margin: 10px auto 0;
    border-radius: 2px;
  }}

  /* Sections */
  .section {{
    margin-bottom: 50px;
  }}
  .section-header {{
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 20px;
  }}
  .section-number {{
    background: var(--gold);
    color: var(--navy);
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 0.95em;
    flex-shrink: 0;
  }}
  .section-title {{
    font-size: 1.55em;
    font-weight: 700;
    color: var(--navy);
  }}

  /* Tables */
  .table-wrap {{
    overflow-x: auto;
    border-radius: 10px;
    box-shadow: 0 2px 12px rgba(27,42,74,0.06);
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    background: var(--white);
    font-size: 0.92em;
  }}
  th {{
    background: var(--navy);
    color: var(--white);
    padding: 12px 16px;
    text-align: left;
    font-weight: 600;
    font-size: 0.85em;
    text-transform: uppercase;
    letter-spacing: 0.4px;
  }}
  td {{
    padding: 10px 16px;
    border-bottom: 1px solid var(--border);
  }}
  tr:last-child td {{ border-bottom: none; }}
  tr:hover {{ background: #F0F4FF; }}
  .center {{ text-align: center; }}

  /* Chart containers */
  .chart-container {{
    background: var(--white);
    border-radius: 12px;
    padding: 28px 24px;
    box-shadow: 0 2px 12px rgba(27,42,74,0.06);
    margin-bottom: 24px;
  }}
  .chart-container canvas {{
    max-height: 420px;
  }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }}

  /* Narrative blocks */
  .narrative {{
    background: var(--white);
    border-left: 4px solid var(--gold);
    padding: 20px 24px;
    margin: 20px 0;
    border-radius: 0 8px 8px 0;
    box-shadow: 0 1px 8px rgba(27,42,74,0.05);
    font-size: 0.95em;
    line-height: 1.7;
    color: var(--slate);
