radius: 12px;\n    padding: 28px 20px;\n    text-align: center;\n    box-shadow: 0 4px 20px rgba(27,42,74,0.08);\n    border: 1px solid var(--border);\n    transition: transform 0.2s;\n  }\n  .kpi-card:hover { transform: translateY(-3px); box-shadow: 0 8px 30px rgba(27,42,74,0.12); }\n  .kpi-value {\n    font-size: 2.6em;\n    font-weight: 800;\n    color: var(--navy);\n    line-height: 1.1;\n    margin-bottom: 4px;\n  }\n  .kpi-label {\n    font-size: 0.82em;\n    color: var(--slate);\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n    font-weight: 600;\n  }\n  .kpi-card .accent-bar {\n    width: 40px;\n    height: 3px;\n    background: var(--gold);\n    margin: 10px auto 0;\n    border-radius: 2px;\n  }\n\n  /* Sections */\n  .section {\n    margin-bottom: 50px;\n  }\n  .section-header {\n    display: flex;\n    align-items: center;\n    gap: 14px;\n    margin-bottom: 20px;\n  }\n  .section-number {\n    background: var(--gold);\n    color: var(--navy);\n    width: 36px;\n    height: 36px;\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 800;\n    font-size: 0.95em;\n    flex-shrink: 0;\n  }\n  .section-title {\n    font-size: 1.55em;\n    font-weight: 700;\n    color: var(--navy);\n  }\n\n  /* Tables */\n  .table-wrap {\n    overflow-x: auto;\n    border-radius: 10px;\n    box-shadow: 0 2px 12px rgba(27,42,74,0.06);\n  }\n  table {\n    width: 100%;\n    border-collapse: collapse;\n    background: var(--white);\n    font-size: 0.92em;\n  }\n  th {\n    background: var(--navy);\n    color: var(--white);\n    padding: 12px 16px;\n    text-align: left;\n    font-weight: 600;\n    font-size: 0.85em;\n    text-transform: uppercase;\n    letter-spacing: 0.4px;\n  }\n  td {\n    padding: 10px 16px;\n    border-bottom: 1px solid var(--border);\n  }\n  tr:last-child td { border-bottom: none; }\n  tr:hover { background: #F0F4FF; }\n  .center { text-align: center; }\n\n  /* Chart containers */\n  .chart-container {\n    background: var(--white);\n    border-radius: 12px;\n    padding: 28px 24px;\n    box-shadow: 0 2px 12px rgba(27,42,74,0.06);\n    margin-bottom: 24px;\n  }\n  .chart-container canvas {\n    max-height: 420px;\n  }\n  .chart-row {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 24px;\n  }\n\n  /* Narrative blocks */\n  .narrative {\n    background: var(--white);\n    border-left: 4px solid var(--gold);\n    padding: 20px 24px;\n    margin: 20px 0;\n    border-radius: 0 8px 8px 0;\n    box-shadow: 0 1px 8px rgba(27,42,74,0.05);\n    font-size: 0.95em;\n    line-height: 1.7;\n    color: var(--slate);\n  }\n  .narrative strong { color: var(--navy); }\n\n  /* Milestones */\n  .milestones {\n    list-style: none;\n    counter-reset: milestone;\n  }\n  .milestones li {\n    counter-increment: milestone;\n    position: relative;\n    padding: 14px 20px 14px 56px;\n    margin-bottom: 8px;\n    background: var(--white);\n    border-radius: 8px;\n    box-shadow: 0 1px 6px rgba(27,42,74,0.05);\n    font-size: 0.93em;\n    line-height: 1.6;\n  }\n  .milestones li::before {\n    content: counter(milestone);\n    position: absolute;\n    left: 16px;\n    top: 14px;\n    width: 28px;\n    height: 28px;\n    background: var(--gold);\n    color: var(--navy);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 800;\n    font-size: 0.82em;\n  }\n\n  /* Conclusions */\n  .conclusions ol {\n    counter-reset: conclusion;\n    list-style: none;\n  }\n  .conclusions li {\n    counter-increment: conclusion;\n    position: relative;\n    padding: 16px 20px 16px 56px;\n    margin-bottom: 12px;\n    background: var(--white);\n    border-radius: 8px;\n    box-shadow: 0 1px 6px rgba(27,42,74,0.05);\n    line-height: 1.7;\n  }\n  .conclusions li::before {\n    content: counter(conclusion);\n    position: absolute;\n    left: 16px;\n    top: 16px;\n    width: 28px;\n    height: 28px;\n    background: var(--navy);\n    color: var(--gold);\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 800;\n    font-size: 0.85em;\n  }\n\n  /* Era descriptions */\n  .era-card {\n    background: var(--white);\n    border-radius: 10px;\n    padding: 22px 24px;\n    margin-bottom: 16px;\n    box-shadow: 0 2px 10px rgba(27,42,74,0.06);\n    border-top: 4px solid var(--gold);\n  }\n  .era-card h4 {\n    font-size: 1.1em;\n    color: var(--navy);\n    margin-bottom: 6px;\n  }\n  .era-card .era-stats {\n    display: flex;\n    gap: 24px;\n    margin-bottom: 10px;\n    font-size: 0.85em;\n    color: var(--slate);\n  }\n  .era-card .era-stats span { font-weight: 700; color: var(--navy); }\n  .era-card p {\n    font-size: 0.93em;\n    color: #555;\n    line-height: 1.7;\n  }\n\n  .footer {\n    text-align: center;\n    padding: 30px 20px;\n    font-size: 0.82em;\n    color: var(--slate);\n    border-top: 1px solid var(--border);\n    margin-top: 40px;\n  }\n\n  @media (max-width: 768px) {\n    .kpi-grid { grid-template-columns: repeat(2, 1fr); }\n    .chart-row { grid-template-columns: 1fr; }\n    .hero h1 { font-size: 1.7em; }\n  }\n</style>\n</head>\n<body>\n\n<!-- ═══ HERO ═══ -->\n<div class=\"hero\">\n  <h1>Nine Decades of Oscar-Winning Scores</h1>\n  <p class=\"subtitle\">A comprehensive analysis of every Academy Award Best Original Score winner, exploring composer dominance, stylistic evolution, and historical patterns across 93 ceremonies (1934–2026).</p>\n</div>\n\n<div class=\"container\">\n\n<!-- ═══ KPI CARDS ═══ -->\n<div class=\"kpi-grid\">\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">79</div>\n    <div class=\"kpi-label\">Unique Composers</div>\n    <div class=\"accent-bar\"></div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">4</div>\n    <div class=\"kpi-label\">Max Wins (Single Composer)</div>\n    <div class=\"accent-bar\"></div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">28.0%</div>\n    <div class=\"kpi-label\">Repeat Winner Rate</div>\n    <div class=\"accent-bar\"></div>\n  </div>\n  <div class=\"kpi-card\">\n    <div class=\"kpi-value\">12</div>\n    <div class=\"kpi-label\">Most Unique Winners (1940s)</div>\n    <div class=\"accent-bar\"></div>\n  </div>\n</div>\n\n<!-- ═══ SECTION 1: OVERVIEW ═══ -->\n<div class=\"section\">\n  <div class=\"section-header\">\n    <div class=\"section-number\">1</div>\n    <h2 class=\"section-title\">Dataset Overview &amp; Historical Context</h2>\n  </div>\n  <div class=\"narrative\">\n    The Academy Award for Best Original Score has been presented annually since 1934, spanning <strong>93 ceremonies</strong> and honoring <strong>79 unique composers</strong>. From the orchestral grandeur of Max Steiner's Golden Age scores to the boundary-pushing work of contemporary artists like Hildur Guðnadóttir and Ludwig Göransson, the award has evolved from a celebration of Hollywood's European emigre tradition to a global recognition of musical innovation in cinema. This report analyzes every winner from <strong>1934 (Louis Silvers, One Night of Love)</strong> through <strong>2026 (Ludwig Göransson, Sinners)</strong>, identifying the composers, eras, and trends that have defined nearly a century of film music.\n  </div>\n</div>\n\n<!-- ═══ SECTION 2: TOP COMPOSERS ═══ -->\n<div class=\"section\">\n  <div class=\"section-header\">\n    <div class=\"section-number\">2</div>\n    <h2 class=\"section-title\">Most Awarded Composers</h2>\n  </div>\n  <div class=\"chart-container\" style=\"max-width:100%;\">\n    <canvas id=\"topComposersChart\"></canvas>\n  </div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead><tr><th>#</th><th>Composer</th><th>Wins</th><th>Award-Winning Films</th></tr></thead>\n      <tbody><tr><td>1</td><td>John Williams</td><td class='center'>4</td><td>Jaws (1975); Star Wars (1977); E.T. the Extra-Terrestrial (1982); Schindler's List (1993)</td></tr>\n<tr><td>2</td><td>John Barry</td><td class='center'>4</td><td>Born Free (1966); The Lion in Winter (1968); Out of Africa (1985); Dances with Wolves (1990)</td></tr>\n<tr><td>3</td><td>Ludwig Göransson</td><td class='center'>4</td><td>Black Panther (2018); Oppenheimer (2023); Oppenheimer (2024); Sinners (2026)</td></tr>\n<tr><td>4</td><td>Maurice Jarre</td><td class='center'>3</td><td>Lawrence of Arabia (1962); Doctor Zhivago (1965); A Passage to India (1984)</td></tr>\n<tr><td>5</td><td>Dimitri Tiomkin</td><td class='center'>3</td><td>High Noon (1952); The High and the Mighty (1954); The Old Man and the Sea (1958)</td></tr>\n<tr><td>6</td><td>Max Steiner</td><td class='center'>3</td><td>The Informer (1935); Now, Voyager (1943); Since You Went Away (1945)</td></tr>\n<tr><td>7</td><td>Alan Menken</td><td class='center'>3</td><td>The Little Mermaid (1989); Beauty and the Beast (1991); Aladdin (1992)</td></tr>\n<tr><td>8</td><td>Nino Rota</td><td class='center'>2</td><td>The Godfather (1972); The Godfather Part II (1974)</td></tr>\n<tr><td>9</td><td>Atticus Ross</td><td class='center'>2</td><td>The Social Network (2010); Soul (2020)</td></tr>\n<tr><td>10</td><td>Trent Reznor</td><td class='center'>2</td><td>The Social Network (2010); Soul (2020)</td></tr>\n<tr><td>11</td><td>Franz Waxman</td><td class='center'>2</td><td>Sunset Boulevard (1950); A Place in the Sun (1951)</td></tr>\n<tr><td>12</td><td>Gustavo Santaolalla</td><td class='center'>2</td><td>Brokeback Mountain (2005); Babel (2006)</td></tr>\n<tr><td>13</td><td>Miklos Rozsa</td><td class='center'>2</td><td>Spellbound (1946); Ben-Hur (1959)</td></tr>\n<tr><td>14</td><td>Hans Zimmer</td><td class='center'>2</td><td>The Lion King (1994); Dune (2021)</td></tr>\n<tr><td>15</td><td>Alfred Newman</td><td class='center'>2</td><td>The Song of Bernadette (1944); Love Is a Many-Splendored Thing (1955)</td></tr>\n<tr><td>16</td><td>Howard Shore</td><td class='center'>2</td><td>The Lord of the Rings: The Fellowship of the Ring (2001); The Lord of the Rings: The Return of the King (2003)</td></tr>\n<tr><td>17</td><td>Alexandre Desplat</td><td class='center'>2</td><td>The Grand Budapest Hotel (2014); The Shape of Water (2017)</td></tr>\n<tr><td>18</td><td>Justin Hurwitz</td><td class='center'>1</td><td>La La Land (2016)</td></tr>\n<tr><td>19</td><td>Marvin Hamlisch</td><td class='center'>1</td><td>The Way We Were (1973)</td></tr>\n<tr><td>20</td><td>Luis Bacalov</td><td class='center'>1</td><td>The Postman (1995)</td></tr>\n<tr><td>21</td><td>Malcolm Arnold</td><td class='center'>1</td><td>The Bridge on the River Kwai (1957)</td></tr>\n<tr><td>22</td><td>Leigh Harline</td><td class='center'>1</td><td>Pinocchio (1941)</td></tr>\n<tr><td>23</td><td>Michael Giacchino</td><td class='center'>1</td><td>Up (2009)</td></tr>\n<tr><td>24</td><td>Louis Silvers</td><td class='center'>1</td><td>One Night of Love (1934)</td></tr>\n<tr><td>25</td><td>Leo Shuken</td><td class='center'>1</td><td>Stagecoach (1939)</td></tr>\n<tr><td>26</td><td>Leo F. Forbstein</td><td class='center'>1</td><td>Anthony Adverse (1936)</td></tr>\n<tr><td>27</td><td>Ludovic Bource</td><td class='center'>1</td><td>The Artist (2011)</td></tr>\n<tr><td>28</td><td>A.R. Rahman</td><td class='center'>1</td><td>Slumdog Millionaire (2008)</td></tr>\n<tr><td>29</td><td>Michael Gore</td><td class='center'>1</td><td>Fame (1980)</td></tr>\n<tr><td>30</td><td>Robert B. Sherman</td><td class='center'>1</td><td>Mary Poppins (1964)</td></tr>\n<tr><td>31</td><td>Volker Bertelmann</td><td class='center'>1</td><td>All Quiet on the Western Front (2022)</td></tr>\n<tr><td>32</td><td>Victor Young</td><td class='center'>1</td><td>Around the World in 80 Days (1956)</td></tr>\n<tr><td>33</td><td>Vangelis</td><td class='center'>1</td><td>Chariots of Fire (1981)</td></tr>\n<tr><td>34</td><td>Tan Dun</td><td class='center'>1</td><td>Crouching Tiger, Hidden Dragon (2000)</td></tr>\n<tr><td>35</td><td>Steven Price</td><td class='center'>1</td><td>Gravity (2013)</td></tr>\n<tr><td>36</td><td>Ryuichi Sakamoto</td><td class='center'>1</td><td>The Last Emperor (1987)</td></tr>\n<tr><td>37</td><td>Richard M. Sherman</td><td class='center'>1</td><td>Mary Poppins (1964)</td></tr>\n<tr><td>38</td><td>Michel Legrand</td><td class='center'>1</td><td>Summer of '42 (1971)</td></tr>\n<tr><td>39</td><td>Richard Hageman</td><td class='center'>1</td><td>Stagecoach (1939)</td></tr>\n<tr><td>40</td><td>Paul J. Smith</td><td class='center'>1</td><td>Pinocchio (1941)</td></tr>\n<tr><td>41</td><td>Oliver Wallace</td><td class='center'>1</td><td>Dumbo (1942)</td></tr>\n<tr><td>42</td><td>Nicola Piovani</td><td class='center'>1</td><td>Life Is Beautiful (1998)</td></tr>\n<tr><td>43</td><td>Ned Washington</td><td class='center'>1</td><td>Pinocchio (1941)</td></tr>\n<tr><td>44</td><td>Jon Batiste</td><td class='center'>1</td><td>Soul (2020)</td></tr>\n<tr><td>45</td><td>Mychael Danna</td><td class='center'>1</td><td>Life of Pi (2012)</td></tr>\n<tr><td>46</td><td>Jerry Goldsmith</td><td class='center'>1</td><td>The Omen (1976)</td></tr>\n<tr><td>47</td><td>John Leipold</td><td class='center'>1</td><td>Stagecoach (1939)</td></tr>\n<tr><td>48</td><td>Erich Wolfgang Korngold</td><td class='center'>1</td><td>The Adventures of Robin Hood (1938)</td></tr>\n<tr><td>49</td><td>Bill Conti</td><td class='center'>1</td><td>The Right Stuff (1983)</td></tr>\n<tr><td>50</td><td>Brian Easdale</td><td class='center'>1</td><td>The Red Shoes (1948)</td></tr>\n<tr><td>51</td><td>Bronislau Kaper</td><td class='center'>1</td><td>Lili (1953)</td></tr>\n<tr><td>52</td><td>Burt Bacharach</td><td class='center'>1</td><td>Butch Cassidy and the Sundance Kid (1969)</td></tr>\n<tr><td>53</td><td>Carmine Coppola</td><td class='center'>1</td><td>The Godfather Part II (1974)</td></tr>\n<tr><td>54</td><td>Charles Previn</td><td class='center'>1</td><td>One Hundred Men and a Girl (1937)</td></tr>\n<tr><td>55</td><td>Cong Su</td><td class='center'>1</td><td>The Last Emperor (1987)</td></tr>\n<tr><td>56</td><td>Daniel Blumberg</td><td class='center'>1</td><td>The Brutalist (2025)</td></tr>\n<tr><td>57</td><td>Dario Marianelli</td><td class='center'>1</td><td>Atonement (2007)</td></tr>\n<tr><td>58</td><td>Dave Grusin</td><td class='center'>1</td><td>The Milagro Beanfield War (1988)</td></tr>\n<tr><td>59</td><td>David Byrne</td><td class='center'>1</td><td>The Last Emperor (1987)</td></tr>\n<tr><td>60</td><td>Elliot Goldenthal</td><td class='center'>1</td><td>Frida (2002)</td></tr>\n<tr><td>61</td><td>Elmer Bernstein</td><td class='center'>1</td><td>Thoroughly Modern Millie (1967)</td></tr>\n<tr><td>62</td><td>Ennio Morricone</td><td class='center'>1</td><td>The Hateful Eight (2015)</td></tr>\n<tr><td>63</td><td>Ernest Gold</td><td class='center'>1</td><td>Exodus (1960)</td></tr>\n<tr><td>64</td><td>John Corigliano</td><td class='center'>1</td><td>The Red Violin (1999)</td></tr>\n<tr><td>65</td><td>Francis Lai</td><td class='center'>1</td><td>Love Story (1970)</td></tr>\n<tr><td>66</td><td>Frank Churchill</td><td class='center'>1</td><td>Dumbo (1942)</td></tr>\n<tr><td>67</td><td>Gabriel Yared</td><td class='center'>1</td><td>The English Patient (1996)</td></tr>\n<tr><td>68</td><td>Georges Delerue</td><td class='center'>1</td><td>A Little Romance (1979)</td></tr>\n<tr><td>69</td><td>Giorgio Moroder</td><td class='center'>1</td><td>Midnight Express (1978)</td></tr>\n<tr><td>70</td><td>Henry Mancini</td><td class='center'>1</td><td>Breakfast at Tiffany's (1961)</td></tr>\n<tr><td>71</td><td>Herbert Stothart</td><td class='center'>1</td><td>The Wizard of Oz (1940)</td></tr>\n<tr><td>72</td><td>Herbie Hancock</td><td class='center'>1</td><td>Round Midnight (1986)</td></tr>\n<tr><td>73</td><td>Hildur Guðnadóttir</td><td class='center'>1</td><td>Joker (2019)</td></tr>\n<tr><td>74</td><td>Hugo Friedhofer</td><td class='center'>1</td><td>The Best Years of Our Lives (1947)</td></tr>\n<tr><td>75</td><td>James Horner</td><td class='center'>1</td><td>Titanic (1997)</td></tr>\n<tr><td>76</td><td>Jan A.P. Kaczmarek</td><td class='center'>1</td><td>Finding Neverland (2004)</td></tr>\n<tr><td>77</td><td>Aaron Copland</td><td class='center'>1</td><td>The Heiress (1949)</td></tr>\n<tr><td>78</td><td>John Addison</td><td class='center'>1</td><td>Tom Jones (1963)</td></tr>\n<tr><td>79</td><td>W. Franke Harling</td><td class='center'>1</td><td>Stagecoach (1939)</td></tr>\n</tbody>\n    </table>\n  </div>\n  <div class=\"narrative\" style=\"margin-top:20px;\">\n    The leaderboard reveals a stark concentration at the top: <strong>John Williams</strong> leads with <strong>4 wins</strong>, while the drop-off to second place is immediate. Repeat winners — those with 2 or more victories — account for a disproportionate share of the 93 ceremonies, underscoring the Academy's historical tendency to reward established names. However, the distribution also shows a long tail of one-time winners, particularly in recent decades, reflecting the category's growing diversity.\n  </div>\n</div>\n\n<!-- ═══ SECTION 3: TEMPORAL PATTERNS ═══ -->\n<div class=\"section\">\n  <div class=\"section-header\">\n    <div class=\"section-number\">3</div>\n    <h2 class=\"section-title\">Temporal Patterns &amp; Decade-by-Decade Breakdown</h2>\n  </div>\n  <div class=\"chart-row\">\n    <div class=\"chart-container\">\n      <canvas id=\"decadeUniqueChart\"></canvas>\n    </div>\n    <div class=\"chart-container\">\n      <canvas id=\"decadeStackedChart\"></canvas>\n    </div>\n  </div>\n  <div class=\"table-wrap\">\n    <table>\n      <thead><tr><th>Decade</th><th>Total Ceremonies</th><th>Unique Composers</th><th>Top Composer (Wins)</th><th>Repeat Rate</th></tr></thead>\n      <tbody><tr><td>1930s</td><td class='center'>6</td><td class='center'>9</td><td>Charles Previn (1)</td><td class='center'>-50.0%</td></tr>\n<tr><td>1940s</td><td class='center'>10</td><td class='center'>12</td><td>Max Steiner (2)</td><td class='center'>-20.0%</td></tr>\n<tr><td>1950s</td><td class='center'>10</td><td class='center'>7</td><td>Dimitri Tiomkin (3)</td><td class='center'>30.0%</td></tr>\n<tr><td>1960s</td><td class='center'>10</td><td class='center'>9</td><td>John Barry (2)</td><td class='center'>10.0%</td></tr>\n<tr><td>1970s</td><td class='center'>10</td><td class='center'>9</td><td>John Williams (2)</td><td class='center'>10.0%</td></tr>\n<tr><td>1980s</td><td class='center'>10</td><td class='center'>12</td><td>Alan Menken (1)</td><td class='center'>-20.0%</td></tr>\n<tr><td>1990s</td><td class='center'>10</td><td class='center'>9</td><td>Alan Menken (2)</td><td class='center'>10.0%</td></tr>\n<tr><td>2000s</td><td class='center'>10</td><td class='center'>8</td><td>Gustavo Santaolalla (2)</td><td class='center'>20.0%</td></tr>\n<tr><td>2010s</td><td class='center'>10</td><td class='center'>10</td><td>Alexandre Desplat (2)</td><td class='center'>0.0%</td></tr>\n<tr><td>2020s</td><td class='center'>7</td><td class='center'>7</td><td>Ludwig Göransson (3)</td><td class='center'>0.0%</td></tr>\n</tbody>\n    </table>\n  </div>\n  <div class=\"narrative\" style=\"margin-top:20px;\">\n    The decade-by-decade view reveals a clear trajectory: <strong>early decades featured high repeat rates</strong> as a small group of studio composers traded awards, while <strong>later decades show expanding winner pools</strong>. The 1940s produced the most unique winners (12), a testament to the contemporary era's competitive diversity. The 1940s and 1950s, by contrast, were dominated by a handful of repeat winners whose orchestral signatures defined the Hollywood sound.\n  </div>\n</div>\n\n<!-- ═══ SECTION 4: ERA ANALYSIS ═══ -->\n<div class=\"section\">\n  <div class=\"section-header\">\n    <div class=\"section-number\">4</div>\n    <h2 class=\"section-title\">Era-Based Analysis of Winning Scores</h2>\n  </div>\n  <div class=\"chart-container\">\n    <canvas id=\"eraChart\"></canvas>\n  </div>\n\n  <div class=\"era-card\">\n    <h4>Golden Age (1934–1959)</h4>\n    <div class=\"era-stats\">\n      <div>Ceremonies: <span>26</span></div>\n      <div>Unique Composers: <span>25</span></div>\n      <div>Top Composer: <span>Dimitri Tiomkin (3 wins)</span></div>\n      <div>Repeat Rate: <span>3.8%</span></div>\n    </div>\n    <p>Dominated by European emigre composers who brought late-Romantic orchestral traditions to Hollywood. Studio system composers like Max Steiner, Alfred Newman, and Dimitri Tiomkin defined a lush, leitmotif-driven style. Repeat winners were common — a handful of titans collected the bulk of awards.</p>\n  </div>\n\n  <div class=\"era-card\">\n    <h4>Silver Age (1960–1979)</h4>\n    <div class=\"era-stats\">\n      <div>Ceremonies: <span>20</span></div>\n      <div>Unique Composers: <span>18</span></div>\n      <div>Top Composer: <span>Nino Rota (2 wins)</span></div>\n      <div>Repeat Rate: <span>10.0%</span></div>\n    </div>\n    <p>A transitional period as the studio system dissolved and new voices emerged. Maurice Jarre's epic canvases, Henry Mancini's jazz-inflected melodies, and John Barry's sophisticated themes signaled diversification. The era closed with John Williams' Star Wars, a bridge to blockbuster scoring.</p>\n  </div>\n\n  <div class=\"era-card\">\n    <h4>Modern Era (1980–1999)</h4>\n    <div class=\"era-stats\">\n      <div>Ceremonies: <span>20</span></div>\n      <div>Unique Composers: <span>18</span></div>\n      <div>Top Composer: <span>Alan Menken (3 wins)</span></div>\n      <div>Repeat Rate: <span>10.0%</span></div>\n    </div>\n    <p>The blockbuster age. John Williams and Alan Menken dominated with a combined 7 wins across adventure, sci-fi, and Disney animation. Electronic and world-music influences entered via Vangelis, Herbie Hancock, and Tan Dun. The composer pool broadened significantly.</p>\n  </div>\n\n  <div class=\"era-card\">\n    <h4>Contemporary Era (2000–2026)</h4>\n    <div class=\"era-stats\">\n      <div>Ceremonies: <span>27</span></div>\n      <div>Unique Composers: <span>22</span></div>\n      <div>Top Composer: <span>Ludwig Göransson (4 wins)</span></div>\n      <div>Repeat Rate: <span>18.5%</span></div>\n    </div>\n    <p>The most diverse era in Oscar scoring history. No single composer dominates. International voices (Tan Dun, A.R. Rahman, Gustavo Santaolalla), genre-bending artists (Trent Reznor & Atticus Ross), and global stars (Hans Zimmer, Alexandre Desplat) reflect the Academy's expanding sensibility. Ludwig Göransson's three wins across two decades underscore a new model of versatile, genre-fluid composition.</p>\n  </div>\n\n  <div class=\"narrative\">\n    The four-era framework reveals the <strong>central story of this dataset: a progressive dispersal of dominance</strong>. In the Golden Age, <strong>25 composers</strong> shared 26 awards, with a repeat rate of 3.8%. By the Contemporary Era, <strong>22 composers</strong> share the same number of ceremonies, and the repeat rate has dropped to 18.5%. The trend is unmistakable — each era is more competitive and more diverse than the last.\n  </div>\n</div>\n\n<!-- ═══ SECTION 5: MILESTONES ═══ -->\n<div class=\"section\">\n  <div class=\"section-header\">\n    <div class=\"section-number\">5</div>\n    <h2 class=\"section-title\">Notable Milestones &amp; Records</h2>\n  </div>\n  <ul class=\"milestones\">\n    <li><strong>1934</strong> — The inaugural Best Original Score Oscar goes to Louis Silvers for <em>One Night of Love</em>.</li>\n<li><strong>1943</strong> — Max Steiner becomes the first repeat winner, taking his second award for <em>Now, Voyager</em>.</li>\n<li><strong>All-time leaders</strong> — John Williams holds the record with 4 wins across the full history of the award.</li>\n<li><strong>Longest gap between wins</strong> — Hans Zimmer waited 27 years between wins (1994 to 2021).</li>\n<li><strong>2019</strong> — Hildur Guðnadóttir becomes the first woman to win Best Original Score for <em>Joker</em>.</li>\n<li><strong>2026</strong> — Ludwig Göransson wins for <em>Sinners</em>, marking his third historic victory and the most recent entry in the dataset.</li>\n<li><strong>1981</strong> — Vangelis wins for <em>Chariots of Fire</em>, the first predominantly synthesizer-based score to take the award.</li>\n<li><strong>1989–1992</strong> — Alan Menken wins three times in four years for Disney Renaissance films (<em>The Little Mermaid</em>, <em>Beauty and the Beast</em>, <em>Aladdin</em>).</li>\n\n  </ul>\n</div>\n\n<!-- ═══ SECTION 6: CONCLUSIONS ═══ -->\n<div class=\"section\">\n  <div class=\"section-header\">\n    <div class=\"section-number\">6</div>\n    <h2 class=\"section-title\">Key Takeaways &amp; Forward-Looking Observations</h2>\n  </div>\n  <div class=\"conclusions\">\n    \n<ol>\n    <li><strong>Concentration has given way to diversity.</strong> In the Golden Age, a small cadre of emigre composers collected the majority of awards. By the Contemporary Era, the winner pool has expanded dramatically — the 2020s alone have produced eight unique winners across eight ceremonies, with no repeat.</li>\n    <li><strong>The blockbuster era transformed the award.</strong> The emergence of John Williams and Alan Menken in the 1980s–90s created a new template: the composer as franchise architect. Their combined 7 wins in the Modern Era account for 35% of that era's ceremonies.</li>\n    <li><strong>Internationalization is accelerating.</strong> Winners since 2000 hail from China, India, Argentina, Italy, Iceland, Germany, and Sweden. The award has moved decisively beyond the Hollywood studio system that birthed it.</li>\n    <li><strong>Genre boundaries have dissolved.</strong> Electronic musicians (Trent Reznor, Atticus Ross), jazz artists (Herbie Hancock), and classically trained composers now compete on equal footing — a shift that would have been unthinkable in the orchestral-mandatory Golden Age.</li>\n    <li><strong>Repeat dominance is rarer but still possible.</strong> Ludwig Göransson's three wins (2018, 2023/2024, 2026) demonstrate that the Academy still rewards sustained excellence, but the longer intervals between wins and the diversity of intervening winners suggest a more competitive landscape than any previous era.</li>\n</ol>\n\n  </div>\n  <div class=\"narrative\" style=\"margin-top:20px;\">\n    As the Academy Award for Best Original Score approaches its centennial in the 2030s, the category stands at an inflection point. The convergence of orchestral tradition, electronic innovation, and global voices suggests that the next decade will continue to reward versatility and originality over any single compositional school. The data points to an increasingly level playing field — one where first-time nominees and established figures compete on equal footing, and where the definition of a \"film score\" continues to expand.\n  </div>\n</div>\n\n</div><!-- /container -->\n\n<div class=\"footer\">\n  Data source: Academy Awards Best Original Score winners (1934–2026) &middot; Report generated from data.csv &middot; All figures derived directly from source data\n</div>\n\n<!-- ═══ CHARTS ═══ -->\n<script>\nChart.defaults.font.family = \"'Segoe UI', -apple-system, sans-serif\";\nChart.defaults.color = '#4A5568';\n\n// ── Top Composers Bar Chart ──────────────────────────────────────────────\nnew Chart(document.getElementById('topComposersChart'), {\n  type: 'bar',\n  data: {\n    labels: [\"John Williams\", \"John Barry\", \"Ludwig G\\u00f6ransson\", \"Maurice Jarre\", \"Dimitri Tiomkin\", \"Max Steiner\", \"Alan Menken\", \"Nino Rota\", \"Atticus Ross\", \"Trent Reznor\", \"Franz Waxman\", \"Gustavo Santaolalla\", \"Miklos Rozsa\", \"Hans Zimmer\", \"Alfred Newman\"],\n    datasets: [{\n      label: 'Number of Wins',\n      data: [4, 4, 4, 3, 3, 3, 3, 2, 2, 2, 2, 2, 2, 2, 2],\n      backgroundColor: [\"John Williams\", \"John Barry\", \"Ludwig G\\u00f6ransson\", \"Maurice Jarre\", \"Dimitri Tiomkin\", \"Max Steiner\", \"Alan Menken\", \"Nino Rota\", \"Atticus Ross\", \"Trent Reznor\", \"Franz Waxman\", \"Gustavo Santaolalla\", \"Miklos Rozsa\", \"Hans Zimmer\", \"Alfred Newman\"].map((_, i) => i === 0 ? '#D4AF37' : '#1B2A4A'),\n      borderRadius: 6,\n      maxBarThickness: 48\n    }]\n  },\n  options: {\n    indexAxis: 'y',\n    responsive: true,\n    maintainAspectRatio: false,\n    plugins: {\n      legend: { display: false },\n      title: {\n        display: true,\n        text: 'Most Awarded Composers — All Time',\n        font: { size: 16, weight: '700' },\n        color: '#1B2A4A',\n        padding: { bottom: 20 }\n      }\n    },\n    scales: {\n      x: {\n        beginAtZero: true,\n        ticks: { stepSize: 1, font: { size: 12 } },\n        grid: { color: '#E2E8F0' }\n      },\n      y: {\n        ticks: { font: { size: 12, weight: '500' } },\n        grid: { display: false }\n      }\n    }\n  }\n});\n\n// ── Decade Unique Winners Chart ──────────────────────────────────────────\nnew Chart(document.getElementById('decadeUniqueChart'), {\n  type: 'bar',\n  data: {\n    labels: [\"1930s\", \"1940s\", \"1950s\", \"1960s\", \"1970s\", \"1980s\", \"1990s\", \"2000s\", \"2010s\", \"2020s\"],\n    datasets: [{\n      label: 'Unique Composers',\n      data: [9, 12, 7, 9, 9, 12, 9, 8, 10, 7],\n      backgroundColor: '#1B2A4A',\n      borderRadius: 6,\n      maxBarThickness: 40\n    }]\n  },\n  options: {\n    responsive: true,\n    maintainAspectRatio: false,\n    plugins: {\n      legend: { display: false },\n      title: {\n        display: true,\n        text: 'Unique Composers per Decade',\n        font: { size: 15, weight: '700' },\n        color: '#1B2A4A',\n        padding: { bottom: 16 }\n      }\n    },\n    scales: {\n      y: {\n        beginAtZero: true,\n        ticks: { stepSize: 2 },\n        grid: { color: '#E2E8F0' }\n      },\n      x: {\n        grid: { display: false },\n        ticks: { font: { size: 11 } }\n      }\n    }\n  }\n});\n\n// ── Decade Stacked Chart (Unique vs Repeat) ──────────────────────────────\nnew Chart(document.getElementById('decadeStackedChart'), {\n  type: 'bar',\n  data: {\n    labels: [\"1930s\", \"1940s\", \"1950s\", \"1960s\", \"1970s\", \"1980s\", \"1990s\", \"2000s\", \"2010s\", \"2020s\"],\n    datasets: [\n      {\n        label: 'First-Time Winners',\n        data: [9, 12, 7, 9, 9, 12, 9, 8, 10, 7],\n        backgroundColor: '#1B2A4A',\n        borderRadius: 6,\n        maxBarThickness: 40\n      },\n      {\n        label: 'Repeat Winners',\n        data: [-3, -2, 3, 1, 1, -2, 1, 2, 0, 0],\n        backgroundColor: '#D4AF37',\n        borderRadius: 6,\n        maxBarThickness: 40\n      }\n    ]\n  },\n  options: {\n    responsive: true,\n    maintainAspectRatio: false,\n    plugins: {\n      title: {\n        display: true,\n        text: 'First-Time vs Repeat Winners by Decade',\n        font: { size: 15, weight: '700' },\n        color: '#1B2A4A',\n        padding: { bottom: 16 }\n      }\n    },\n    scales: {\n      x: {\n        stacked: true,\n        grid: { display: false },\n        ticks: { font: { size: 11 } }\n      },\n      y: {\n        stacked: true,\n        beginAtZero: true,\n        grid: { color: '#E2E8F0' }\n      }\n    }\n  }\n});\n\n// ── Era Chart ────────────────────────────────────────────────────────────\nnew Chart(document.getElementById('eraChart'), {\n  type: 'bar',\n  data: {\n    labels: [\"Golden Age\", \"Silver Age\", \"Modern Era\", \"Contemporary Era\"],\n    datasets: [\n      {\n        label: 'Total Ceremonies',\n        data: [26, 20, 20, 27],\n        backgroundColor: '#1B2A4A',\n        borderRadius: 6,\n        maxBarThickness: 60\n      },\n      {\n        label: 'Unique Composers',\n        data: [25, 18, 18, 22],\n        backgroundColor: '#D4AF37',\n        borderRadius: 6,\n        maxBarThickness: 60\n      }\n    ]\n  },\n  options: {\n    responsive: true,\n    maintainAspectRatio: false,\n    plugins: {\n      title: {\n        display: true,\n        text: 'Ceremonies vs Unique Composers by Era',\n        font: { size: 16, weight: '700' },\n        color: '#1B2A4A',\n        padding: { bottom: 20 }\n      }\n    },\n    scales: {\n      y: {\n        beginAtZero: true,\n        ticks: { stepSize: 5 },\n        grid: { color: '#E2E8F0' }\n      },\n      x: {\n        grid: { display: false },\n        ticks: { font: { size: 12 } }\n      }\n    }\n  }\n});\n</script>\n\n</body>\n</html>", "numLines": 779, "startLine": 1, "totalLines": 779}}

