    f.write(html)

print(f"Report generated at /app/output/final_report.html")
print(f"KPIs: {unique_composers} unique composers, {max_wins} max wins (3-way tie), {repeat_winner_rate:.1f}% repeat rate")
print(f"Decade with most unique: {max_unique_val} (tie: {', '.join(d['decade'] for d in decades_with_most_unique)})")
print(f"Era repeat rates: {[e['repeat_rate'] for e in era_data]}")

import pandas as pd
import json

# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')

# ── Parse individual composers from multi-composer entries ─────────────────
def split_composers(composer_str):
    return [p.strip() for p in composer_str.split(',')]

rows = []
for _, row in df.iterrows():
    for c in split_composers(row['Composer']):
        rows.append({'Year': row['Year'], 'Film': row['Film'], 'Composer': c})
df_ind = pd.DataFrame(rows)

# ── KPI Computations ──────────────────────────────────────────────────────
total_ceremonies = len(df)
unique_composers = df_ind['Composer'].nunique()

# Wins per composer
composer_wins = df_ind.groupby('Composer')['Year'].apply(list).reset_index()
composer_wins['WinCount'] = composer_wins['Year'].apply(len)
composer_wins = composer_wins.sort_values('WinCount', ascending=False).reset_index(drop=True)

max_wins = composer_wins['WinCount'].max()
# All composers tied at max
max_wins_composers = composer_wins[composer_wins['WinCount'] == max_wins]['Composer'].tolist()

# Repeat winner rate (per ceremony): a ceremony counts as "repeat" if ANY composer
# in that year had won in a prior year.
first_win_year = {}
repeat_ceremonies = 0
ceremony_is_repeat = {}
for _, row in df.iterrows():
    year = row['Year']
    composers = split_composers(row['Composer'])
    is_repeat = False
    for c in composers:
        if c in first_win_year and first_win_year[c] < year:
            is_repeat = True
        if c not in first_win_year:
            first_win_year[c] = year
    if is_repeat:
        repeat_ceremonies += 1
    ceremony_is_repeat[year] = is_repeat

repeat_winner_rate = (repeat_ceremonies / total_ceremonies) * 100

# Decade analysis
def year_to_decade(y):
    return f"{(y // 10) * 10}s"

df['Decade'] = df['Year'].apply(year_to_decade)
df_ind['Decade'] = df_ind['Year'].apply(year_to_decade)

decade_data = []
for decade in sorted(df['Decade'].unique()):
    sub = df[df['Decade'] == decade]
    sub_ind = df_ind[df_ind['Decade'] == decade]
    n_ceremonies = len(sub)
    n_unique = sub_ind['Composer'].nunique()
    # Top composer in this decade
    top_comp = sub_ind.groupby('Composer').size().sort_values(ascending=False)
    top_name = top_comp.index[0]
    top_count = int(top_comp.iloc[0])
    # Repeat rate: fraction of ceremonies in this decade won by a repeat composer
    n_repeat = sum(1 for y in sub['Year'] if ceremony_is_repeat.get(y, False))
    repeat_pct = round((n_repeat / n_ceremonies) * 100, 1) if n_ceremonies > 0 else 0
    decade_data.append({
        'decade': decade,
        'n_ceremonies': n_ceremonies,
        'n_unique': n_unique,
        'top_composer': top_name,
        'top_composer_wins': top_count,
        'n_repeat': n_repeat,
        'repeat_pct': repeat_pct
    })

# Decade with most unique winners
max_unique_val = max(d['n_unique'] for d in decade_data)
decades_with_most_unique = [d for d in decade_data if d['n_unique'] == max_unique_val]

# ── Era analysis ──────────────────────────────────────────────────────────
def year_to_era(y):
    if y <= 1959:
        return 'Golden Age (1934–1959)'
    elif y <= 1979:
        return 'Silver Age (1960–1979)'
    elif y <= 1999:
        return 'Modern Era (1980–1999)'
    else:
        return 'Contemporary Era (2000–2026)'

df['Era'] = df['Year'].apply(year_to_era)
df_ind['Era'] = df_ind['Year'].apply(year_to_era)

era_data = []
for era in ['Golden Age (1934–1959)', 'Silver Age (1960–1979)', 'Modern Era (1980–1999)', 'Contemporary Era (2000–2026)']:
    sub = df[df['Era'] == era]
    sub_ind = df_ind[df_ind['Era'] == era]
    n_ceremonies = len(sub)
    n_unique = sub_ind['Composer'].nunique()
    top_comp = sub_ind.groupby('Composer').size().sort_values(ascending=False)
    top_name = top_comp.index[0]
    top_count = int(top_comp.iloc[0])
    n_repeat = sum(1 for y in sub['Year'] if ceremony_is_repeat.get(y, False))
    repeat_rate = round((n_repeat / n_ceremonies) * 100, 1) if n_ceremonies > 0 else 0
    era_data.append({
        'era': era,
        'n_ceremonies': n_ceremonies,
        'n_unique': n_unique,
        'top_composer': top_name,
        'top_composer_wins': top_count,
        'n_repeat': n_repeat,
        'repeat_rate': repeat_rate
    })

# ── Milestones ────────────────────────────────────────────────────────────
# Longest gap between wins for a repeat composer
gaps = []
for _, row in composer_wins[composer_wins['WinCount'] >= 2].iterrows():
    years = sorted(row['Year'])
    for i in range(1, len(years)):
        gaps.append({
            'composer': row['Composer'],
            'gap': years[i] - years[i-1],
            'from_year': years[i-1],
            'to_year': years[i]
        })
longest_gap = max(gaps, key=lambda x: x['gap']) if gaps else None

# ── Chart data ────────────────────────────────────────────────────────────
top_n = 15
top_composers = composer_wins.head(top_n)
top_chart_labels = top_composers['Composer'].tolist()
top_chart_values = top_composers['WinCount'].tolist()

# Highlight all max-win composers in gold
top_chart_colors = ['#D4AF37' if v == max_wins else '#1B2A4A' for v in top_chart_values]

decade_labels = [d['decade'] for d in decade_data]
decade_unique_values = [d['n_unique'] for d in decade_data]
decade_repeat_pct = [d['repeat_pct'] for d in decade_data]

era_labels = [e['era'].split('(')[0].strip() for e in era_data]
era_unique_values = [e['n_unique'] for e in era_data]
era_ceremonies_values = [e['n_ceremonies'] for e in era_data]

# ── Build HTML components ─────────────────────────────────────────────────
# KPI card for "Most Unique Winners"
if len(decades_with_most_unique) > 1:
    decade_kpi_label = f"Most Unique Winners ({' / '.join(d['decade'] for d in decades_with_most_unique)})"
else:
    decade_kpi_label = f"Most Unique Winners ({decades_with_most_unique[0]['decade']})"

# Top composers narrative
if len(max_wins_composers) > 1:
    top_narrative = f"The leaderboard is anchored by a three-way tie: <strong>{', '.join(max_wins_composers)}</strong> each hold <strong>{max_wins} wins</strong>. Barry's victories span from the 1960s to the 1990s; Williams dominated the blockbuster era of the late 1970s through the 1990s; and Göransson's wins cluster in the late 2010s–2020s. The distribution below them — seven composers with 2 wins each, and 62 one-time winners — underscores a long-tail pattern: a small elite accumulates multiple awards while the vast majority of Oscar-winning composers take home the statuette exactly once."
else:
    top_narrative = f"<strong>{max_wins_composers[0]}</strong> leads with <strong>{max_wins} wins</strong>. Repeat winners — those with 2 or more victories — account for a disproportionate share of the 93 ceremonies, underscoring the Academy's historical tendency to reward established names."

# Top composers table
top_table_rows = ""
for i, (_, row) in enumerate(composer_wins.iterrows()):
    films = []
    for y in sorted(row['Year']):
        film = df[df['Year'] == y]['Film'].values[0]
        films.append(f"{film} ({y})")
    films_str = "; ".join(films)
    top_table_rows += f"<tr><td>{i+1}</td><td>{row['Composer']}</td><td class='center'>{row['WinCount']}</td><td>{films_str}</td></tr>\n"

# Decade table
decade_table_rows = ""
for d in decade_data:
    decade_table_rows += (
        f"<tr><td>{d['decade']}</td><td class='center'>{d['n_ceremonies']}</td>"
        f"<td class='center'>{d['n_unique']}</td>"
        f"<td>{d['top_composer']} ({d['top_composer_wins']})</td>"
        f"<td class='center'>{d['repeat_pct']}%</td></tr>\n"
    )

# Decade narrative
decade_narrative = f"The decade-by-decade view reveals a clear trajectory: <strong>early decades featured higher repeat rates</strong> as a small group of studio composers traded awards, while <strong>later decades show expanding and more diverse winner pools</strong>. The {decades_with_most_unique[0]['decade']} and 1980s tie for the most unique winners ({max_unique_val}), though for different reasons — the 1940s owe their count to multi-composer awards inflating individual names, while the 1980s reflect genuine breadth with 12 unique voices across 10 ceremonies."

# Era descriptions
era_descriptions = {
    'Golden Age (1934–1959)': 'Dominated by European emigre composers who brought late-Romantic orchestral traditions to Hollywood. Studio system composers like Max Steiner, Alfred Newman, and Dimitri Tiomkin defined a lush, leitmotif-driven style. A handful of titans — Steiner, Tiomkin, Waxman, Rozsa — collected the bulk of repeat awards.',
    'Silver Age (1960–1979)': 'A transitional period as the studio system dissolved and new voices emerged. Maurice Jarre\'s epic canvases, Henry Mancini\'s jazz-inflected melodies, and John Barry\'s sophisticated themes signaled diversification. The era closed with John Williams\' Star Wars, a bridge to blockbuster scoring.',
    'Modern Era (1980–1999)': 'The blockbuster age. John Williams and Alan Menken dominated with a combined 7 wins across adventure, sci-fi, and Disney animation. Electronic and world-music influences entered via Vangelis, Herbie Hancock, and Tan Dun. The composer pool broadened significantly.',
    'Contemporary Era (2000–2026)': 'The most diverse era in Oscar scoring history. International voices (Tan Dun, A.R. Rahman, Gustavo Santaolalla), genre-bending artists (Trent Reznor & Atticus Ross), and global stars (Hans Zimmer, Alexandre Desplat) reflect the Academy\'s expanding sensibility. Ludwig Göransson\'s multiple wins across two decades underscore a new model of versatile, genre-fluid composition.'
}

# Era narrative
era_narrative = f"The four-era framework reveals the <strong>central story of this dataset: a progressive dispersal of dominance</strong>. In the Golden Age, <strong>{era_data[0]['n_unique']} composers</strong> shared {era_data[0]['n_ceremonies']} awards, with a repeat rate of {era_data[0]['repeat_rate']}%. In the Contemporary Era, <strong>{era_data[3]['n_unique']} composers</strong> share {era_data[3]['n_ceremonies']} awards, with a repeat rate of {era_data[3]['repeat_rate']}%. The gap between ceremonies and unique composers narrows over time — a sign that the award increasingly rotates among new talent rather than concentrating among repeat winners."

# Milestones
milestones_html = ""
milestones_html += "<li><strong>1934</strong> — The inaugural Best Original Score Oscar goes to Louis Silvers for <em>One Night of Love</em>.</li>\n"
milestones_html += "<li><strong>1943</strong> — Max Steiner becomes the first repeat winner, taking his second award for <em>Now, Voyager</em>.</li>\n"
milestones_html += f"<li><strong>All-time leaders</strong> — {', '.join(max_wins_composers)} share the record with {max_wins} wins each.</li>\n"
if longest_gap:
    milestones_html += f"<li><strong>Longest gap between wins</strong> — {longest_gap['composer']} waited {longest_gap['gap']} years between wins ({longest_gap['from_year']} to {longest_gap['to_year']}).</li>\n"
milestones_html += "<li><strong>2019</strong> — Hildur Guðnadóttir becomes the first woman to win Best Original Score for <em>Joker</em>.</li>\n"
